# Generated by curate-skills
# Workflow: wordcount_mapreduce_histogram
# Function: map_word_counts

"""Map phase of the wordcount MapReduce workflow.

Runs as 4 parallel instances. Every instance downloads the same full corpus,
splits it into contiguous equal shards (one per rank), and counts the words of
its own shard only. The partial counts are uploaded as a per-rank JSON object so
no two instances write the same file.
"""

import json
import os
import string
import tempfile
from collections import Counter

# Characters stripped from the two ends of a raw whitespace token before counting.
PUNCTUATION = string.punctuation + "‘’“”–—…"


def map_word_counts(folder: str, input1: str, output1: str) -> None:
    r = faasr_rank()
    rank = int(r["rank"])
    max_rank = int(r["max_rank"])

    if rank < 1 or rank > max_rank:
        message = "map_word_counts: rank %d outside 1..%d" % (rank, max_rank)
        faasr_log(message)
        raise ValueError(message)

    remote_input = input1.format(rank=rank)
    remote_output = output1.format(rank=rank)

    tmp_dir = tempfile.gettempdir()
    local_input = os.path.join(tmp_dir, "corpus_rank%d.txt" % rank)
    local_output = os.path.join(tmp_dir, "partial_counts_%d.json" % rank)

    faasr_log(
        "map_word_counts: rank %d/%d downloading %s from folder %s"
        % (rank, max_rank, remote_input, folder)
    )
    faasr_get_file(local_file=local_input, remote_folder=folder, remote_file=remote_input)

    with open(local_input, "r", encoding="utf-8") as handle:
        text = handle.read()

    tokens = text.split()
    total = len(tokens)
    if total == 0:
        message = (
            "map_word_counts: rank %d read an empty corpus from %s in folder %s"
            % (rank, remote_input, folder)
        )
        faasr_log(message)
        raise ValueError(message)

    # Contiguous equal shards, one per rank; any remainder goes to the first
    # (total % max_rank) shards so every token is counted exactly once.
    base, remainder = divmod(total, max_rank)
    start = (rank - 1) * base + min(rank - 1, remainder)
    size = base + (1 if rank <= remainder else 0)
    shard = tokens[start:start + size]

    faasr_log(
        "map_word_counts: rank %d/%d owns tokens [%d:%d) of %d (%d tokens)"
        % (rank, max_rank, start, start + size, total, len(shard))
    )

    counts = Counter()
    for token in shard:
        word = token.strip(PUNCTUATION).lower()
        if word:
            counts[word] += 1

    partial = {word: counts[word] for word in sorted(counts)}

    with open(local_output, "w", encoding="utf-8") as handle:
        json.dump(partial, handle, ensure_ascii=False, indent=2, sort_keys=True)
        handle.write("\n")

    faasr_put_file(local_file=local_output, remote_folder=folder, remote_file=remote_output)
    faasr_log(
        "map_word_counts: rank %d wrote %s (%d distinct words, %d counted tokens)"
        % (rank, remote_output, len(partial), sum(partial.values()))
    )
